package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class SaveClaimCreated {
    public void save(@Val ValidClaim request, @Val Person person, Claims claims, Sheets sheets, Audit audit, @Val RollupFigures before, Rollup rollup, Periods periods,
            net.officefloor.hq.app.setting.Settings settings, ClaimLog log,
            ObjectResponse<ResponseEntity<ClaimResponse>> response) throws InvalidClaimException {
        String sheetId = person.getSheetId();
        LocalDate date = request.date() != null ? request.date() : sheets.today(sheetId);
        if (periods.isClosed(sheetId, date)) {
            throw new InvalidClaimException("No claim can be added inside a closed period");
        }
        if (!person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        ValidateClaim.checkCorrects(request, sheetId, person.getId(), claims);
        Claim claim = claims.add(sheetId, person.getId(), request.amount(), date, request.note(), request.corrects(),
                date.plusDays(settings.termsFor(sheetId, person.gradeOn(date), date)));
        log.record(claim, person, request.user());
        audit.recordOnCommit(ClaimAudit.line("CLAIM_ADDED", request.user(), person, claim, claim.getNumber()));
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new ResponseEntity<>(ClaimResponse.from(claim), HttpStatus.CREATED));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves a DRAFT, OPEN or PENDING claim to another person on the sheet; only the roles the sheet's reassign permission allows
 * (by default a steward) move a claim.
 * It keeps its number and date but loses any figure a statement bound it to: it is live again until
 * its new person's next statement.
 */
public class ApplyReassign {
    public void apply(@Val ReassignRequest request, @Val Claim claim, People people, Settings settings,
            Out<ClaimMove> move) throws ClaimStatusRefusedException {
        if (!settings.allows(claim.getSheetId(), request.user(), "reassign")) {
            throw new ClaimStatusRefusedException("Your role may not move a claim to another person");
        }
        ClaimStatus status = claim.getStatus();
        if (status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING) {
            throw new ClaimStatusRefusedException("A " + status + " claim cannot move to another person");
        }
        Person to = null;
        try {
            to = people.find(claim.getSheetId(), Long.parseLong(request.toPersonId()));
        } catch (NumberFormatException e) {
            // not an id this app assigned
        }
        if (to == null) {
            throw new ClaimStatusRefusedException("No such person to move the claim to");
        }
        if (to.getId() == claim.getPersonId()) {
            throw new ClaimStatusRefusedException("The claim is already that person's");
        }
        Person from = people.find(claim.getSheetId(), claim.getPersonId());
        claim.setPersonId(to.getId());
        claim.setStated(false);
        claim.setStatedDue(null);
        move.set(new ClaimMove(from, to));
    }
}
